begin;
select set_config('test.a',gen_random_uuid()::text,true),set_config('test.b',gen_random_uuid()::text,true);
insert into auth.users(id,email,email_confirmed_at,is_anonymous) values(current_setting('test.a')::uuid,'a-isolation@fooddf.invalid',now(),false),(current_setting('test.b')::uuid,'b-isolation@fooddf.invalid',now(),false);
select set_config('request.jwt.claim.sub',current_setting('test.a'),true);
set local role authenticated;
select set_config('test.ra',(public.fooddf_create_restaurant('{"name":"Loja A","slug":"isolation-fixture-a","state":"DF","city":"Brasília"}')).id,true);
select set_config('request.jwt.claim.sub',current_setting('test.b'),true);
select set_config('test.rb',(public.fooddf_create_restaurant('{"name":"Loja B","slug":"isolation-fixture-b","state":"DF","city":"Brasília"}')).id,true);
insert into public.products(id,restaurant_id,name,price,category) values('isolation-product-b',current_setting('test.rb'),'Produto B',1000,'Categoria B');
insert into public.restaurant_plans(restaurant_id,trial_started_at) values(current_setting('test.rb'),now());
select set_config('request.jwt.claim.sub',current_setting('test.a'),true);
do $$ declare n integer; begin
 if not public.fooddf_has_panel_access() then raise exception 'Owner cannot access panel'; end if;
 if (select count(*) from public.restaurants)<>1 then raise exception 'Owner sees another restaurant'; end if;
 if exists(select 1 from public.products) or exists(select 1 from public.restaurant_plans) then raise exception 'Cross-tenant data readable'; end if;
 update public.restaurants set name='Own update' where id=current_setting('test.ra');get diagnostics n=row_count;if n<>1 then raise exception 'Own update failed'; end if;
 update public.restaurants set name='Foreign update' where id=current_setting('test.rb');get diagnostics n=row_count;if n<>0 then raise exception 'Cross-tenant update'; end if;
 begin insert into public.products(restaurant_id,name,price,category) values(current_setting('test.rb'),'Foreign insert',1000,'Test');raise exception 'Cross-tenant insert';exception when insufficient_privilege then null;end;
 begin insert into storage.objects(bucket_id,name) values('restaurant-images',current_setting('test.rb')||'/attack.png');raise exception 'Cross-tenant upload';exception when insufficient_privilege then null;end;
 begin perform public.fooddf_create_restaurant('{"name":"Duplicate","slug":"isolation-duplicate","state":"DF","city":"Brasília"}');raise exception 'Duplicate account restaurant';exception when raise_exception then if sqlerrm<>'Sua conta já possui um restaurante' then raise;end if;end;
 insert into public.categories(restaurant_id,name) values(current_setting('test.ra'),'Minha categoria');
 if exists(select 1 from public.fooddf_admin_metrics(current_setting('test.rb'))) then raise exception 'Foreign metrics visible';end if;
end $$;
reset role;
update auth.users set email_confirmed_at=null where id=current_setting('test.a')::uuid;
set local role authenticated;
do $$ begin if public.fooddf_has_panel_access() or exists(select 1 from public.restaurants) then raise exception 'Unverified account authorized';end if;end $$;
set local role anon;
do $$ begin
 if not exists(select id from public.restaurants where slug='brasa-burger') then raise exception 'Public catalog broken';end if;
 begin perform owner_id from public.restaurants;raise exception 'Private owner exposed';exception when insufficient_privilege then null;end;
end $$;
rollback;
select 'PASS: isolated tenant read/write, product insert, private plans/metrics, foreign storage denial, own edits, duplicate registration denial, unverified denial, public catalog' as result;
